FD3=["front_desk","night_audit","gm"]; FDG=["front_desk","gm"]
PCI="https://www.pcisecuritystandards.org/standards/"; FTC_S="https://consumer.ftc.gov/articles/how-recognize-and-avoid-phishing-scams"; CB="https://www.consumerfinance.gov/ask-cfpb/what-is-a-chargeback-en-2031/"
CF="https://www.secretservice.gov/investigations/counterfeit"; INN="https://www.revisor.mn.gov/statutes/cite/327.70"; INNK="https://www.revisor.mn.gov/statutes/cite/327.73"; ADAH="https://www.ada.gov/topics/hotels/"
add(FD3,"role",[
("recovery","easy","A guest says their room wasn't cleaned. What's the best first response?","Un huésped dice que no le limpiaron el cuarto. ¿Mejor primera respuesta?",["Apologize, thank them for telling you, and offer a fix and timing","Say housekeeping is busy","Blame the shift","Ask why they didn't call earlier"],["Disculparte, agradecer que te lo diga y ofrecer solución y hora","Decir que limpieza está ocupada","Culpar al turno","Preguntar por qué no llamó antes"],"Service recovery: listen, apologize, solve, follow up.","Escuchar, disculparse, resolver, dar seguimiento.",BP),
("recovery","med","What's the last step of good service recovery that's often skipped?","¿Cuál es el último paso de la recuperación que suele olvidarse?",["Following up to make sure the fix worked","Writing a policy","Charging a fee","Telling the GM only"],["Dar seguimiento para confirmar que se resolvió","Escribir una política","Cobrar","Solo avisar al gerente"],"Follow-up turns complaints into loyalty.","El seguimiento genera lealtad.",BP),
("recovery","med","A guest is yelling at the desk. What helps de-escalate?","Un huésped grita en recepción. ¿Qué ayuda a calmarlo?",["Stay calm, lower your voice, listen and repeat back their concern","Yell back","Walk away mid-sentence","Laugh"],["Mantener la calma, bajar la voz, escuchar y repetir su queja","Gritarle","Irte a media frase","Reírte"],"Calm tone and active listening de-escalate.","Tono calmado y escucha activa.",BP),
("recovery","hard","When should you offer compensation (points, discount) for a complaint?","¿Cuándo ofrecer compensación por una queja?",["After fixing the issue, within your authority, matched to the impact","Always, before listening","Never","Only if they threaten a review"],["Después de resolver, dentro de tu autoridad y según el impacto","Siempre, antes de escuchar","Nunca","Solo si amenazan con reseña"],"Fix first; compensate proportionally.","Primero resolver; compensar según el caso.",BP),
("recovery","med","A guest posts a bad review. Who should reply, and how?","Un huésped deja una mala reseña. ¿Quién responde y cómo?",["The GM or designee — thank, apologize, address the issue, invite them back","Anyone, defensively","Nobody","Argue the facts publicly"],["El gerente o designado: agradecer, disculparse, atender y invitar de nuevo","Cualquiera, a la defensiva","Nadie","Discutir en público"],"Professional replies help future guests.","Responder profesional ayuda.",BP),
("recovery","easy","Noise complaint from a guest at 11 p.m. First step?","Queja de ruido a las 11 p. m. ¿Primer paso?",["Thank them, call the noisy room politely, and follow up with the guest","Ignore it","Move the complainer immediately","Call police first"],["Agradecer, llamar con cortesía al cuarto ruidoso y dar seguimiento","Ignorarla","Cambiar al que se queja de inmediato","Llamar a la policía primero"],"Escalate only if needed.","Escalar solo si hace falta.",BP),
("upsell","easy","What's a good way to offer a room upgrade?","¿Cuál es una buena forma de ofrecer mejora de cuarto?",["Describe a benefit that fits their trip and quote the difference","Push every guest hard","Only mention price","Never offer"],["Describir un beneficio que le sirva y dar la diferencia","Presionar a todos","Solo decir el precio","Nunca ofrecer"],"Benefit-based offers feel helpful, not pushy.","Ofrecer beneficios ayuda.",BP),
("upsell","med","A family of 5 checks into a standard room. What could you offer?","Una familia de 5 llega a un cuarto estándar. ¿Qué ofrecerías?",["A suite or larger room for space — if available","Nothing","A smaller room","A parking spot"],["Una suite o cuarto más grande, si hay","Nada","Un cuarto más chico","Estacionamiento"],"Match offers to needs.","Ofrecer según la necesidad.",BP),
("upsell","med","When is the best moment to offer an upgrade at check-in?","¿Cuándo es mejor ofrecer mejora al registrarse?",["After greeting and confirming the reservation, before keys are made","After they leave","While the line is out the door","Never"],["Después de saludar y confirmar, antes de hacer llaves","Cuando se van","Con la fila larga","Nunca"],"Natural moment in the flow.","Momento natural.",BP),
("reservations","easy","What details must you confirm when taking a reservation?","¿Qué datos confirmas al tomar una reservación?",["Name, dates, room type, rate, guests, and how to contact them","Only name","Only dates","Only card"],["Nombre, fechas, tipo de cuarto, tarifa, personas y contacto","Solo nombre","Solo fechas","Solo tarjeta"],"Read-backs prevent errors.","Repetir evita errores.",BP),
("reservations","med","Why read back the dates and rate to the caller?","¿Por qué repetir fechas y tarifa al cliente?",["Catches mistakes before the stay","It's polite filler","Required by phone company","No reason"],["Detecta errores antes de la estancia","Solo cortesía","Lo pide la compañía","Por nada"],"Confirmation prevents disputes.","Evita disputas.",BP),
("reservations","med","A guest wants to cancel. What do you check first?","Un huésped quiere cancelar. ¿Qué revisas primero?",["The rate's cancellation policy and deadline","Their age","Their car","Nothing — just cancel"],["La política de cancelación de su tarifa y fecha límite","Su edad","Su carro","Nada"],"Rates differ — prepaid vs flexible.","Las tarifas cambian.",BP),
("reservations","hard","What's a 'no-show'?","¿Qué es un 'no-show'?",["A guest with a guaranteed reservation who never arrives or cancels","A guest who leaves early","A walk-in","A cancelled room"],["Huésped con reservación garantizada que no llega ni cancela","Huésped que sale antes","Sin reservación","Cuarto cancelado"],"No-show policies apply the guarantee.","Se aplica la garantía.",BP),
("reservations","med","The hotel is oversold and a guest must be 'walked'. What's expected?","El hotel está sobrevendido y hay que reubicar a un huésped. ¿Qué se espera?",["Apologize, book them at a nearby comparable hotel, and arrange transport per policy","Tell them to find a room","Put them in the lobby","Charge them"],["Disculparse, reservarle hotel cercano similar y transporte según política","Que busque cuarto","Dejarlo en el lobby","Cobrarle"],"Walk procedures protect the guest experience.","El procedimiento protege al huésped.",BP),
("policy","easy","A guest under the minimum check-in age wants a room. What do you do?","Un menor de la edad mínima quiere cuarto. ¿Qué haces?",["Politely decline per policy — the registered guest must meet the age","Give it anyway","Ask a stranger to sign","Charge extra"],["Negarlo con cortesía según la política","Darlo igual","Que firme un desconocido","Cobrar extra"],"Age policies are part of the registration contract.","La edad es parte del registro.",BP),
("policy","med","Why match photo ID to the name on the reservation and card?","¿Por qué comparar identificación con reservación y tarjeta?",["Prevents fraud and protects the real guest","Only for marketing","It's optional","For points only"],["Evita fraude y protege al huésped real","Solo mercadeo","Es opcional","Solo puntos"],"ID check is basic fraud control.","Control básico de fraude.",BP),
("policy","med","What is an 'incidental hold'?","¿Qué es una 'retención para gastos'?",["A temporary authorization on the card to cover possible charges","A fee kept forever","A cash tip","A tax"],["Una autorización temporal en la tarjeta para posibles cargos","Un cargo permanente","Propina","Impuesto"],"Authorizations are released after checkout per the bank.","Se libera tras la salida según el banco.",BP),
("policy","hard","A guest's debit card hold still shows days after checkout. What do you explain?","Al huésped le sigue la retención en su débito días después. ¿Qué le explicas?",["We released it; the bank controls how fast it drops off","We kept the money","It's permanent","Call the police"],["Ya la liberamos; el banco decide cuánto tarda","Nos quedamos el dinero","Es permanente","Que llame a la policía"],"Banks control authorization release timing.","El banco controla los tiempos.",CB),
("law","hard","Minnesota law lets a hotel limit its liability for guest valuables if it…","La ley de MN limita la responsabilidad del hotel por valores si…",["Offers a safe and posts the required notice","Says so verbally","Has cameras","Never — always liable"],["Ofrece caja fuerte y pone el aviso requerido","Lo dice de palabra","Tiene cámaras","Nunca"],"MN Stat. 327.70 (innkeeper liability with safe and notice).","Estatuto 327.70 de MN.",INN),
("law","hard","Under Minnesota law, can a hotel remove a guest who's disorderly or won't pay?","Según la ley de MN, ¿puede el hotel sacar a un huésped que causa desorden o no paga?",["Yes, the innkeeper may eject them, using police if needed","No, never","Only after 30 days","Only with a court order"],["Sí, el hotelero puede sacarlo, con policía si hace falta","Nunca","Solo tras 30 días","Solo con orden judicial"],"MN Stat. 327.73.","Estatuto 327.73.",INNK),
("ada","med","A guest asks for an accessible room you have open. Can you give it to a non-disabled guest first?","Un huésped pide un cuarto accesible disponible. ¿Lo das primero a alguien sin discapacidad?",["Accessible rooms should be held for guests who need them until others are booked","Yes, first come","Yes, always","Only VIPs"],["Los accesibles se reservan para quienes los necesitan hasta que se agoten los demás","Sí, el primero","Siempre","Solo VIP"],"DOJ ADA hotel reservations rule.","Regla ADA de reservaciones del DOJ.",ADAH),
("ada","easy","A deaf guest asks how they'll know about a fire alarm. What do you offer?","Un huésped sordo pregunta cómo sabrá de una alarma. ¿Qué le ofreces?",["A hearing-accessible kit or room with visual alarms","Nothing","Tell them to stay awake","A whistle"],["Un kit o cuarto auditivo con alarma visual","Nada","Que no duerma","Un silbato"],"ADA requires communication features.","La ADA exige estos recursos.",ADAH),
("cash","easy","When you start a shift with a bank, what do you do first?","Al iniciar turno con fondo, ¿qué haces primero?",["Count it and sign that it matches","Start selling","Count at the end only","Trust it"],["Contarlo y firmar que cuadra","Empezar a cobrar","Contar solo al final","Confiar"],"Verifies accountability.","Garantiza responsabilidad.",BP),
("cash","med","How do you give change to avoid mistakes?","¿Cómo das cambio sin errores?",["Leave the guest's bill out until change is counted back","Put the bill away first","Guess","Round up"],["Dejar el billete fuera hasta contar el cambio","Guardar el billete primero","Adivinar","Redondear"],"Prevents 'I gave you a $50' disputes.","Evita disputas.",BP),
("cash","med","How can you check a $100 bill is real?","¿Cómo revisas que un billete de $100 sea real?",["Tilt it for the color-shifting 100 and 3-D ribbon; check the watermark","Smell it","Look at the serial only","Fold it"],["Inclinarlo: 100 que cambia de color, cinta 3D y marca de agua","Olerlo","Solo serie","Doblarlo"],"US Secret Service/uscurrency.gov features.","Elementos oficiales.","https://www.uscurrency.gov/denominations/100"),
("cash","hard","You suspect a counterfeit bill. What should you do?","Sospechas un billete falso. ¿Qué haces?",["Don't return it if safe to keep; note the passer's description and call police","Give it back and say nothing","Spend it","Tear it"],["Si es seguro, no devolverlo; anotar la descripción y llamar a la policía","Devolverlo","Gastarlo","Romperlo"],"Secret Service guidance.","Guía del Servicio Secreto.",CF),
("cash","easy","Can you leave your cash drawer open and walk away?","¿Puedes dejar la caja abierta e irte?",["No — lock it every time you step away","Yes, briefly","Yes, at night","If a guest watches"],["No; ciérrala siempre","Sí, un momento","Sí, de noche","Si un huésped vigila"],"Drawer control.","Control de caja.",BP),
("payments","med","A caller asks you to read back the full card number on file. What do you do?","Alguien pide que le leas el número completo de la tarjeta. ¿Qué haces?",["Never — confirm only the last 4 digits","Read it slowly","Email it","Text it"],["Nunca; solo confirmar los últimos 4","Leerlo despacio","Enviarlo por correo","Mandarlo por mensaje"],"PCI DSS protects cardholder data.","PCI DSS protege los datos.",PCI),
("payments","med","Can you write a guest's card number on a sticky note?","¿Puedes anotar el número de tarjeta en un papelito?",["No — never store card data outside the secure system","Yes, then shred","Yes, if hidden","Only at night"],["No; nunca guardes datos fuera del sistema seguro","Sí y luego triturar","Sí si está escondido","Solo de noche"],"PCI DSS.","PCI DSS.",PCI),
("payments","hard","An email from 'corporate' asks you to wire money urgently and keep it secret. What is it likely?","Un correo de 'corporativo' pide transferir dinero urgente y en secreto. ¿Qué es?",["A phishing/scam — verify by phone with a known number and tell your GM","A normal request","A bonus","A test you must pass by paying"],["Fraude; verifica por teléfono con número conocido y avisa al gerente","Normal","Un bono","Prueba que pasas pagando"],"FTC: urgency + secrecy = scam.","FTC: urgencia y secreto = fraude.",FTC_S),
("scam","med","A caller says they're 'from the front desk' and asks a guest for their card. What should guests know?","Alguien llama al huésped diciendo que es 'de recepción' y pide su tarjeta. ¿Qué deben saber?",["The desk won't call asking for card numbers — come to the desk instead","It's normal","Give it","Read the CVV"],["Recepción no llama pidiendo tarjetas; que bajen a recepción","Es normal","Darla","Dar el CVV"],"Common hotel phone scam (FTC).","Fraude común.",FTC_S),
("security","easy","Someone at the desk asks for a key to room 214 saying it's their wife's room. What do you do?","Alguien pide llave del 214 diciendo que es de su esposa. ¿Qué haces?",["Only give keys to registered guests with ID — offer to call the room","Give it","Ask the room color","Give a temporary key"],["Solo a huéspedes registrados con ID; ofrecer llamar al cuarto","Dársela","Preguntar el color","Llave temporal"],"Key control protects guests.","Control de llaves.",BP),
("security","med","When saying a room number at check-in, what's best?","Al dar el número de cuarto, ¿qué es mejor?",["Write it on the key packet instead of saying it aloud","Announce it","Shout it","Post it"],["Escribirlo en el sobre en vez de decirlo","Anunciarlo","Gritarlo","Publicarlo"],"Others may overhear.","Otros escuchan.",BP),
("security","med","A guest reports their wallet stolen from the room. What do you do?","Un huésped reporta robo de cartera del cuarto. ¿Qué haces?",["Take it seriously, notify the manager, offer to call police, and document it","Say it's not our problem","Search their room alone","Accuse housekeeping"],["Tomarlo en serio, avisar al gerente, ofrecer llamar a policía y documentar","No es problema nuestro","Revisar solo","Acusar a limpieza"],"Document and escalate.","Documentar y escalar.",BP),
("security","hard","Police arrive asking for a guest's room number without a warrant. What's the standard practice?","La policía pide un número de cuarto sin orden. ¿Práctica estándar?",["Involve the manager; follow company policy on law-enforcement requests (registry privacy)","Give everything instantly","Refuse to talk","Call the guest to warn"],["Llamar al gerente y seguir la política (privacidad del registro)","Dar todo","Negarse a hablar","Avisar al huésped"],"Supreme Court (City of LA v. Patel) recognized hotel registry privacy.","La Corte Suprema reconoció la privacidad del registro.","https://www.oyez.org/cases/2014/13-1175"),
("phone","easy","How should you answer the hotel phone?","¿Cómo contestas el teléfono del hotel?",["Greeting, hotel name, your name, 'How may I help you?'","'Yeah?'","Hotel name only","Silence"],["Saludo, nombre del hotel, tu nombre, '¿En qué le ayudo?'","'¿Sí?'","Solo hotel","Silencio"],"A standard greeting sets the tone.","Saludo estándar.",BP),
("phone","med","You must put a caller on hold. What's polite?","Debes poner en espera. ¿Qué es cortés?",["Ask permission, wait for the answer, and check back within a minute","Just press hold","Hang up","Leave them 10 minutes"],["Pedir permiso, esperar y volver en un minuto","Solo poner espera","Colgar","Dejarlo 10 minutos"],"Respect callers' time.","Respeta su tiempo.",BP),
("checkin","easy","A guest arrives at 10 a.m. but check-in is 3 p.m. What can you offer?","Llega a las 10 a. m. y la entrada es a las 3. ¿Qué ofreces?",["Check availability for early check-in or store bags and take their number","Tell them to come back","Charge double","Send them to another hotel"],["Ver si hay entrada temprana o guardar maletas y tomar su número","Que vuelva","Cobrar doble","Mandarlo a otro hotel"],"Flexibility builds goodwill.","La flexibilidad ayuda.",BP),
("checkin","med","Why use the guest's name during check-in?","¿Por qué usar el nombre del huésped al registrarlo?",["It personalizes service and shows attention","It's required by law","To slow things down","No reason"],["Personaliza y muestra atención","Ley","Para hacerlo lento","Por nada"],"Personal touch.","Toque personal.",BP),
("checkout","med","A guest disputes a charge at checkout. What first?","Un huésped disputa un cargo. ¿Primero?",["Listen, review the folio together, and fix errors or explain clearly","Refuse","Remove all charges","Call security"],["Escuchar, revisar el folio juntos y corregir o explicar","Negarse","Quitar todo","Llamar a seguridad"],"Clear folio review resolves most disputes.","Revisar resuelve casi todo.",BP),
("checkout","easy","At checkout, what simple question can catch problems?","Al salir, ¿qué pregunta sencilla detecta problemas?",["'How was your stay?' — and listen","'Pay now'","'Anything else to buy?'","None"],["'¿Cómo estuvo su estancia?' y escuchar","'Pague ya'","'¿Algo más?'","Ninguna"],"Last chance for recovery.","Última oportunidad.",BP),
("emergency","med","A guest calls the desk with chest pain. What do you do?","Un huésped llama con dolor de pecho. ¿Qué haces?",["Call 911, send someone with the AED, and meet EMS at the door","Tell them to rest","Send them a taxi","Call back later"],["Llamar al 911, mandar a alguien con el DEA y recibir a la ambulancia","Que descanse","Mandar taxi","Llamar después"],"Fast EMS and AED save lives.","El 911 y el DEA salvan vidas.",AED),
("emergency","med","During a fire alarm, what's the desk's key job?","Durante una alarma de incendio, ¿qué hace recepción?",["Follow the plan: call 911/confirm, grab the in-house guest list, direct people out, meet firefighters","Keep checking in","Silence the alarm","Hide"],["Seguir el plan: 911, lista de huéspedes, guiar la salida, recibir a bomberos","Seguir registrando","Apagar la alarma","Esconderse"],"Front desk supports evacuation.","Recepción apoya la evacuación.",FIRE),
("emergency","med","A guest's child is missing in the hotel. What do you do?","Se perdió el niño de un huésped. ¿Qué haces?",["Get a description, alert all staff to watch exits, search, and call 911 quickly","Wait an hour","Tell them to look","Announce room numbers"],["Pedir descripción, alertar al personal y salidas, buscar y llamar al 911 pronto","Esperar una hora","Que busquen ellos","Anunciar cuartos"],"Code Adam-style response.","Respuesta tipo Código Adam.","https://www.missingkids.org/gethelpnow/isyourchildmissing"),
("handoff","easy","At shift change, what should be in the pass-on log?","En el cambio de turno, ¿qué va en la bitácora?",["Open issues, guest requests, VIPs, and follow-ups","Nothing","Your lunch","Gossip"],["Pendientes, peticiones, VIP y seguimientos","Nada","Tu comida","Chismes"],"A good log prevents dropped requests.","La bitácora evita olvidos.",BP),
("loyalty","easy","Why ask every guest if they're a loyalty member?","¿Por qué preguntar a cada huésped si es miembro?",["They earn points and benefits, and the hotel gains repeat guests","It's not useful","Only for VIPs","For taxes"],["Ganan puntos y beneficios y el hotel gana lealtad","No sirve","Solo VIP","Impuestos"],"Enrollment drives repeat business.","Genera regreso.",BP),
("tone","easy","Which phrase is better at the desk?","¿Qué frase es mejor en recepción?",["'Let me see what I can do'","'That's not possible'","'Policy says no'","'Not my problem'"],["'Déjeme ver qué puedo hacer'","'No se puede'","'La política dice que no'","'No es mi problema'"],"Positive language keeps guests open.","Lenguaje positivo.",BP),
("language","med","A guest speaks only Spanish and you don't. What helps?","Un huésped solo habla español y tú no. ¿Qué ayuda?",["Ask a Spanish-speaking coworker or use a translation app politely","Speak louder in English","Ignore","Send them away"],["Pedir a un compañero que hable español o usar traductor con cortesía","Hablar más fuerte en inglés","Ignorar","Mandarlo"],"Find a way to communicate.","Busca comunicarte.",BP),
])
add(["night_audit","gm"],"role",[
("audit","easy","What's the night audit's main job?","¿Cuál es el trabajo principal de la auditoría nocturna?",["Balance the day's charges and payments and close the business day","Clean the lobby only","Take reservations only","Sleep"],["Cuadrar cargos y pagos del día y cerrar el día","Solo limpiar","Solo reservar","Dormir"],"Night audit reconciles and rolls the date.","Concilia y cambia de día.",BP),
("audit","med","Before running the audit, what should you check?","Antes de correr la auditoría, ¿qué revisas?",["All arrivals checked in or marked no-show, room charges posted, and cash balanced","Only the TV","Only the coffee","Nothing"],["Llegadas registradas o no-show, cargos y caja cuadrada","Solo tele","Solo café","Nada"],"Pre-audit checklist prevents errors.","La lista previa evita errores.",BP),
("audit","med","What is ADR?","¿Qué es el ADR?",["Average Daily Rate: room revenue ÷ rooms sold","Rooms sold ÷ rooms available","Total revenue","Guests per room"],["Tarifa promedio: ingreso por cuartos ÷ cuartos vendidos","Vendidos ÷ disponibles","Ingreso total","Huéspedes por cuarto"],"Standard industry metric (STR).","Métrica estándar (STR).","https://str.com/data-insights/resources/glossary"),
("audit","med","What is occupancy?","¿Qué es la ocupación?",["Rooms sold ÷ rooms available","ADR × rooms","Revenue ÷ guests","Arrivals today"],["Cuartos vendidos ÷ disponibles","ADR × cuartos","Ingreso ÷ huéspedes","Llegadas de hoy"],"STR glossary.","Glosario STR.","https://str.com/data-insights/resources/glossary"),
("audit","hard","What is RevPAR?","¿Qué es el RevPAR?",["Room revenue ÷ rooms available (or ADR × occupancy)","Revenue per guest","Rooms sold","Total profit"],["Ingreso por cuartos ÷ disponibles (o ADR × ocupación)","Ingreso por huésped","Vendidos","Utilidad"],"STR glossary.","Glosario STR.","https://str.com/data-insights/resources/glossary"),
("audit","hard","80 rooms sold of 100, ADR $120. What's RevPAR?","80 de 100 vendidos, ADR $120. ¿RevPAR?",["$96","$120","$150","$80"],["$96","$120","$150","$80"],"0.80 × $120 = $96.","0.80 × $120 = $96.","https://str.com/data-insights/resources/glossary"),
("audit","med","Your cash drawer is $20 short at audit. What do you do?","Tu caja tiene $20 de menos. ¿Qué haces?",["Recount, check transactions, and report it honestly to the manager","Add your own money silently","Change the report","Ignore"],["Recontar, revisar movimientos y reportarlo al gerente","Poner tu dinero","Cambiar el reporte","Ignorar"],"Honest variance reporting.","Reportar con honestidad.",BP),
("audit","med","What's a 'room and rate' discrepancy check?","¿Qué es revisar 'cuarto y tarifa'?",["Comparing every in-house room's rate to its reservation/rate code","Counting towels","Checking lights","Calling guests"],["Comparar la tarifa de cada cuarto ocupado con su reservación","Contar toallas","Revisar luces","Llamar huéspedes"],"Catches wrong rates before posting.","Detecta tarifas mal.",BP),
("audit","med","Why compare housekeeping room status with the front desk system?","¿Por qué comparar el estado de limpieza con el sistema?",["To catch skips, sleepers and wrong statuses","For fun","To count beds","No reason"],["Para detectar 'skips', 'sleepers' y estados mal","Diversión","Contar camas","Por nada"],"Room status reconciliation.","Conciliación de estado.",BP),
("audit","hard","What is a 'skip' at the front desk?","¿Qué es un 'skip' en recepción?",["A guest who left without paying or checking out","A late arrival","A no-show","A room upgrade"],["Huésped que se fue sin pagar ni salir","Llegada tarde","No-show","Mejora"],"Skips must be reported and pursued.","Se reportan.",BP),
("audit","hard","What is a 'sleeper'?","¿Qué es un 'sleeper'?",["A room shown occupied in the system but actually vacant","A guest asleep","A cot","A no-show"],["Cuarto ocupado en sistema pero vacío","Huésped dormido","Catre","No-show"],"Status errors cost revenue.","Errores cuestan dinero.",BP),
("night","med","A walk-in arrives at 2 a.m. without ID. What do you do?","Llega alguien a las 2 a. m. sin identificación. ¿Qué haces?",["Follow policy — ID is required; politely decline if none","Rent it anyway","Ask for cash double","Let them sleep in the lobby"],["Seguir la política: se requiere ID; negar con cortesía","Rentar igual","Cobrar doble","Que duerma en el lobby"],"ID policy applies 24/7.","Aplica siempre.",BP),
("night","med","Overnight, how do you keep the lobby secure?","De noche, ¿cómo mantienes seguro el lobby?",["Follow door/lock procedures, watch cameras, and walk rounds per policy","Prop doors open","Sleep","Leave the desk unattended"],["Seguir cierres, ver cámaras y hacer rondas","Dejar puertas abiertas","Dormir","Dejar la recepción sola"],"Night security routine.","Rutina de seguridad.",BP),
("night","med","A non-guest is sleeping in the lobby at 3 a.m. What do you do?","Alguien que no es huésped duerme en el lobby a las 3 a. m. ¿Qué haces?",["Approach calmly, ask if they need help, and follow policy (call police if unsafe)","Yell","Ignore forever","Physically remove them"],["Acercarte con calma, preguntar si necesita ayuda y seguir la política","Gritar","Ignorar","Sacarlo a la fuerza"],"Safety and dignity.","Seguridad y dignidad.",BP),
("night","easy","You're alone overnight and feel unsafe. What should you do?","Estás sola de noche y te sientes insegura. ¿Qué haces?",["Call the manager on duty or 911 — don't confront","Handle it alone","Leave the building","Ignore"],["Llamar al gerente de turno o al 911; no enfrentar","Resolverlo sola","Salir","Ignorar"],"Your safety first.","Tu seguridad primero.",BP),
("night","med","Why print or save an in-house guest list overnight?","¿Por qué imprimir la lista de huéspedes de noche?",["If the system or power fails during an emergency, you know who's in the building","For marketing","To call guests","No reason"],["Si falla el sistema en emergencia, sabes quién está","Mercadeo","Llamar","Por nada"],"Emergency readiness.","Preparación.",FIRE),
("night","hard","Why back up reports before rolling the date?","¿Por qué respaldar reportes antes de cambiar la fecha?",["Once rolled, the prior day can't easily be changed — you need records","For decoration","It's optional","To print coupons"],["Una vez cerrado, no se cambia fácil; necesitas registro","Adorno","Opcional","Cupones"],"Audit trail.","Rastro de auditoría.",BP),
("night","med","A guest calls at 4 a.m. locked out of their room in a towel. What do you do?","Un huésped llama a las 4 a. m. encerrado fuera en toalla. ¿Qué haces?",["Verify identity discreetly (name, details matching registration), then help them in","Refuse","Laugh","Give a key without checking"],["Verificar identidad con discreción y luego ayudarlo","Negar","Reírte","Dar llave sin verificar"],"Balance kindness and security.","Amabilidad y seguridad.",BP),
])
